const $=id=>document.getElementById(id),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let catalogue={cars:[],locations:[]},bookingId=crypto.randomUUID(),feedbackId=crypto.randomUUID(),reviewId,reviewBooking,customerSession=null,customerBookings=[];
async function api(path,options={}){const r=await fetch(path,{credentials:'same-origin',...options,headers:{...(typeof options.body==='string'?{'Content-Type':'application/json'}:{}),...options.headers}});let d;try{d=await r.json();}catch{throw Error('Could not reach GoRide. Please sign in again or retry.');}if(!r.ok)throw Error(d.error||'Please retry.');return d;}
function options(){const city=$('location').value,mode=$('mode').value,previous=$('car').value;const cars=catalogue.cars.filter(c=>c.locationIds.includes(city)&&(mode==='self'?c.selfEnabled:c.driverEnabled));$('car').innerHTML=cars.map(c=>`<option value="${esc(c.id)}">${esc(c.name)}</option>`).join('');if(cars.some(c=>c.id===previous))$('car').value=previous;$('request-button').disabled=!cars.length;}
async function load(){try{const {bookings}=await api('/api/customer/bookings');customerBookings=bookings;$('bookings').innerHTML=bookings.length?bookings.map(b=>`<article class="account-card"><div class="booking-top"><h3>${esc(b.car_name)}</h3><span class="booking-status">${b.status==='confirmed'?'Accepted':esc(b.status)}</span></div><div class="booking-details"><span>${esc(b.location)} · ${b.mode==='self'?'Self-drive':'Chauffeur'}<br>${GoRideBooking.schedule(b)}</span><span>${esc(b.name)} · Age ${b.age}<br>${esc(b.phone)}</span><span>Requested ${esc(new Date(b.created_at).toLocaleDateString())}<br>Reference ${esc(b.id.slice(0,8))}</span></div>${GoRideBooking.trip(b)}${GoRideBooking.quote(b)}${b.quoted_total==null||b.quote_details?'':`<p><strong>Agreed rental total: ₹${b.quoted_total.toLocaleString('en-IN')}</strong> · Payment is not collected here.</p>`}${GoRidePayments.render(b)}${GoRideCancellations.render(b)}${b.decision_note?`<p class="private-note"><strong>GoRide update:</strong> ${esc(b.decision_note)}</p>`:''}<p class="private-note">Documents are private to you and the GoRide owner. Upload JPG, PNG or WebP, up to 8 MB. Aadhaar is optional: mask the first eight digits before uploading. GoRide does not automatically mask or verify images.</p>${['licence','aadhaar'].map(kind=>{const doc=b.documents.find(d=>d.kind===kind);return `<div class="document-row"><strong>${kind==='licence'?'Driving licence':'Masked Aadhaar (optional)'}</strong>${doc?`<a href="/api/customer/documents/${esc(doc.id)}" target="_blank" rel="noopener">View image</a><button class="secondary" data-delete="${esc(doc.id)}">Delete image</button>`:'<span>No image uploaded</span>'}${!['completed','cancelled','rejected'].includes(b.status)?`<label>Choose ${doc?'replacement':'image'}<input type="file" accept="image/jpeg,image/png,image/webp" data-upload="${esc(b.id)}" data-kind="${kind}"></label>`:''}</div>`;}).join('')}${!['completed','cancelled','rejected'].includes(b.status)?`<label class="consent"><input type="checkbox" data-consent="${esc(b.id)}"> I consent to GoRide storing and reviewing these images for this rental. Any Aadhaar image is masked to show only its last four digits.</label>`:''}${b.status==='completed'?`<button class="primary" data-review="${esc(b.id)}">Write a review</button>`:''}</article>`).join(''):'<div class="account-card booking-empty"><span class="empty-road" aria-hidden="true">↗</span><h3>Your next journey starts here</h3><p>You haven’t requested a car yet. Explore the fleet or send your first request.</p><a class="primary" href="/&#35;fleet">Explore cars</a></div>';}catch(e){$('account-error').textContent=e.message;}}
$('booking-form').onsubmit=async e=>{e.preventDefault();const f=e.target,v=Object.fromEntries(new FormData(f));$('request-button').disabled=true;try{const result=await api('/api/customer/bookings',{method:'POST',body:JSON.stringify({...v,id:bookingId,age:Number(v.age),consent:f.elements.consent.checked,alertConsent:f.elements.alertConsent.checked})});bookingId=crypto.randomUUID();$('booking-message').textContent='Request saved. GoRide will contact you to confirm availability and price. Add your documents below.';await load();}catch(e){$('booking-message').textContent=e.message;}finally{options();}};
$('location').onchange=options;$('mode').onchange=options;$('reload').onclick=load;
$('bookings').addEventListener('change',async e=>{const input=e.target;if(!input.dataset.upload)return;const file=input.files[0];if(!file)return;const consent=document.querySelector(`[data-consent="${input.dataset.upload}"]`).checked;if(!consent){$('account-error').textContent='Please confirm document consent before uploading.';input.value='';return;}if(file.size>8*1024*1024||!['image/jpeg','image/png','image/webp'].includes(file.type)){$('account-error').textContent='Choose a JPG, PNG or WebP image up to 8 MB.';return;}input.disabled=true;$('account-error').textContent='Uploading private image…';try{await api(`/api/customer/bookings/${input.dataset.upload}/documents/${input.dataset.kind}`,{method:'POST',headers:{'Content-Type':file.type,'X-Document-Consent':'yes','X-Masked-Aadhaar':'yes'},body:file});$('account-error').textContent='';await load();}catch(e){$('account-error').textContent=e.message;input.disabled=false;}});
$('bookings').onclick=async e=>{const del=e.target.closest('[data-delete]'),review=e.target.closest('[data-review]');if(del&&confirm('Permanently delete this document image?')){try{await api('/api/customer/documents/'+del.dataset.delete,{method:'DELETE'});await load();}catch(e){$('account-error').textContent=e.message;}}if(review){reviewBooking=review.dataset.review;reviewId=crypto.randomUUID();$('review-form').reset();$('review-message').textContent='';$('review-dialog').showModal();}};
$('close-review').onclick=()=>$('review-dialog').close();
async function sendFeedback(form,kind,id,bookingId,messageId){const button=form.querySelector('button');button.disabled=true;try{const v=Object.fromEntries(new FormData(form));await api('/api/customer/feedback',{method:'POST',body:JSON.stringify({...v,id,kind,bookingId,rating:Number(v.rating),publishConsent:form.elements.publishConsent?.checked||false})});$(messageId).textContent=kind==='review'?'Review submitted for owner approval.':'Your private feedback has been sent.';form.reset();return true;}catch(e){$(messageId).textContent=e.message;return false;}finally{button.disabled=false;}}
$('feedback-form').onsubmit=async e=>{e.preventDefault();if(await sendFeedback(e.target,'feedback',feedbackId,null,'feedback-message'))feedbackId=crypto.randomUUID();};
$('review-form').onsubmit=async e=>{e.preventDefault();await sendFeedback(e.target,'review',reviewId,reviewBooking,'review-message');};
(async()=>{try{const session=await api('/api/customer/session');customerSession=session;const nickname=(session.displayName||'Rider');$('account-name').textContent=nickname.charAt(0).toUpperCase()+nickname.slice(1);$('account-avatar').textContent=nickname.charAt(0).toUpperCase();$('account-greeting').textContent='Hi, '+nickname.charAt(0).toUpperCase()+nickname.slice(1)+'.';$('session').textContent=session.verifiedPhone?'Signed in with '+session.phone:(session.preview?'Private test account: ':'Signed in as ')+session.email;if(session.verifiedPhone){const phoneInput=$('booking-form').elements.phone;phoneInput.value=session.phone;phoneInput.readOnly=true;}catalogue=await api('/api/catalog');$('location').innerHTML=catalogue.locations.map(l=>`<option value="${esc(l.id)}">${esc(l.name)}</option>`).join('');const params=new URLSearchParams(location.search);if(catalogue.locations.some(l=>l.id===params.get('location'))) $('location').value=params.get('location');options();if(catalogue.cars.some(c=>c.id===params.get('car')))$('car').value=params.get('car');const today=new Date(Date.now()+330*60000).toISOString().slice(0,10);for(const input of document.querySelectorAll('input[type=date]'))input.min=today;await load();}catch(e){$('account-error').textContent=e.message;}})();

async function loadNotices(){if(document.hidden)return;try{const {notifications}=await api('/api/customer/notifications');const box=$('customer-notifications');box.innerHTML=notifications.length?notifications.map(n=>`<div class="notice ${n.read_at?'':'notice-unread'}"><p>${esc(n.message)}</p><small>${esc(new Date(n.created_at).toLocaleString())}</small>${n.read_at?'':`<button class="secondary" data-read-notice="${esc(n.id)}">Mark read</button>`}</div>`).join(''):'<p>No booking updates yet. Decisions will appear here automatically while this screen is open.</p>';if(!document.querySelector('#bookings input:focus')&&!$('review-dialog').open&&!cancelDialog.open)await load();}catch(e){$('account-error').textContent=e.message;}}
$('customer-notifications').onclick=async e=>{const b=e.target.closest('[data-read-notice]');if(!b)return;try{await api('/api/customer/notifications/'+encodeURIComponent(b.dataset.readNotice),{method:'PUT',body:'{}'});await loadNotices();}catch(e){$('account-error').textContent=e.message;}};
queueMicrotask(loadNotices);setInterval(loadNotices,20000);window.addEventListener('focus',loadNotices);

$('customer-signout').onclick=async e=>{e.preventDefault();if(customerSession?.preview){location.href='/signout-with-chatgpt?return_to=%2Flogin';return;}try{await api('/api/customer-auth/logout',{method:'POST',body:'{}'});location.replace('/login');}catch(err){$('account-error').textContent=err.message;}};

const cancelDialog=document.createElement('dialog');cancelDialog.id='cancel-request-dialog';cancelDialog.setAttribute('aria-labelledby','cancel-request-title');cancelDialog.innerHTML='<h2 id="cancel-request-title">Request cancellation</h2><p id="cancel-request-trip"></p><p class="cancellation-help">Your booking stays active until GoRide approves. Applicable charges or refunds will be confirmed separately.</p><form id="cancel-request-form"><label for="cancel-reason">Why would you like to cancel?</label><textarea id="cancel-reason" name="reason" maxlength="1000" rows="4" required placeholder="Tell GoRide what has changed"></textarea><p id="cancel-request-error" role="alert"></p><div class="decision-actions"><button class="primary" type="submit">Send cancellation request</button><button class="secondary" type="button" id="close-cancel-request">Keep booking</button></div></form>';document.body.append(cancelDialog);
let cancelBooking=null,cancelId=null,cancelSending=false;
$('close-cancel-request').onclick=()=>{if(!cancelSending)cancelDialog.close();};cancelDialog.addEventListener('cancel',event=>{if(cancelSending)event.preventDefault();});
$('bookings').addEventListener('click',event=>{const button=event.target.closest('[data-request-cancellation]');if(!button)return;cancelBooking=customerBookings.find(item=>item.id===button.dataset.requestCancellation);if(!cancelBooking)return;cancelId=crypto.randomUUID();$('cancel-request-form').reset();$('cancel-request-trip').textContent=cancelBooking.car_name+' · '+cancelBooking.start_date+' · '+cancelBooking.id.slice(0,8);$('cancel-request-error').textContent='';cancelDialog.showModal();});
$('cancel-request-form').onsubmit=async event=>{event.preventDefault();const button=event.target.querySelector('[type=submit]');button.disabled=true;cancelSending=true;try{await api('/api/customer/bookings/'+cancelBooking.id+'/cancellations',{method:'POST',body:JSON.stringify({id:cancelId,version:cancelBooking.version,reason:event.target.elements.reason.value})});cancelDialog.close();$('account-error').textContent='';await load();await loadNotices();}catch(error){$('cancel-request-error').textContent=error.message;}finally{button.disabled=false;cancelSending=false;}};

function openRequest(){const panel=$('new-request');panel.open=true;}$('new-trip-link').addEventListener('click',openRequest);document.querySelector('.account-sidebar a[href="#new-request"]').addEventListener('click',openRequest);if(location.hash==='#new-request'||new URLSearchParams(location.search).has('car'))openRequest();
